fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// Replays one harness command.
fn run(cmd: &str) -> String {
    let (kind, args) = cmd.split_once(' ').unwrap();
    match kind {
        "ext" => run_ext(args),
        "clsid" => run_clsid(args),
        _ => run_time(kind, args),
    }
}

fn run_ext(args: &str) -> String {
    let mut store = ExtraChunks::default();
    args.split(' ')
        .map(|op| run_op(&mut store, op))
        .collect::<Vec<_>>()
        .join(" ")
}

/// `w:<ckid>:<hex>` writes a chunk. `r:<ckid>:<cap|->` reads one into a `cap`-byte buffer, or
/// with a NULL buffer for `-`. The reply is `<hr>/<size>/<buffer>`.
fn run_op(store: &mut ExtraChunks, op: &str) -> String {
    let mut parts = op.splitn(3, ':');
    let kind = parts.next().unwrap();
    let ckid = u32::from_str_radix(parts.next().unwrap(), 16).unwrap();
    let arg = parts.next().unwrap();
    if kind == "w" {
        store.write_chunk(ckid, &unhex(arg));
        return "00000000".into();
    }
    let cap = (arg != "-").then(|| arg.parse::<usize>().unwrap());
    let mut out = vec![0xEE; cap.unwrap_or(0)];
    let dst = if cap.is_some() {
        Some(out.as_mut_slice())
    } else {
        None
    };
    let (hr, size) = match store.read_chunk(ckid, dst) {
        Ok(size) => (0, size),
        Err(hr) => (hr, 0),
    };
    let data = if cap.is_some() { hex(&out) } else { "-".into() };
    format!("{hr:08x}/{size}/{data}")
}

fn run_clsid(arg: &str) -> String {
    let s = match arg {
        "-" => None,
        "@" => Some(&b""[..]),
        _ => Some(arg.as_bytes()),
    };
    match clsid_from_str(s) {
        Ok(id) => format!("ok:{}", hex(&id)),
        Err(hr) => format!("err:{hr:08x}"),
    }
}

/// `<start> <length> <rate> <scale> <value>`.
fn run_time(kind: &str, args: &str) -> String {
    let n: Vec<&str> = args.split(' ').collect();
    let st = StreamTiming {
        start: n[0].parse().unwrap(),
        length: n[1].parse().unwrap(),
        rate: n[2].parse().unwrap(),
        scale: n[3].parse().unwrap(),
    };
    let value = n[4].parse().unwrap();
    let r = if kind == "s2t" {
        sample_to_time(st, value)
    } else {
        time_to_sample(st, value)
    };
    r.to_string()
}

#[test]
fn oracle_rows_match_wine() {
    for (cmd, reply) in ROWS {
        assert_eq!(run(cmd), *reply, "{cmd}");
    }
}
